1	const PROCESSING_FEE = 5;
2	
3	type ItemType = "sword" | "amulet" | "staff" | "potion" | "rune" | "moonstone";
4	
5	const BASE_PREMIUM_BY_TYPE: Record<ItemType, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	const INSURANCE_VALUE_BY_TYPE: Record<ItemType, number> = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	};
22	
23	type Item = {
24	  type: ItemType;
25	  material?: string;
26	  enchantment?: number;
27	  cursed?: boolean;
28	};
29	
30	type QuoteStep = { op: "quote"; items: Item[] };
31	
32	type Damage = { itemType: ItemType; amount: number };
33	
34	type Incident = { cause: string; damages: Damage[] };
35	
36	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
37	
38	type Step = QuoteStep | ClaimStep;
39	
40	type Customer = { yearsWithMHPCO: number };
41	
42	type Scenario = { customer: Customer; steps: Step[] };
43	
44	type QuoteResult = { premium: number };
45	
46	type ClaimResult = { payout: number; remainingCap: number };
47	
48	type Result = QuoteResult | ClaimResult;
49	
50	// A policy created by a quote step, tracked so later claims can draw on its cap.
51	type Policy = { items: Item[]; remainingCap: number };
52	
53	const COMPONENT_BLOCK_SIZE = 3;
54	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
55	
56	const COMPONENT_TYPES: ReadonlySet<ItemType> = new Set(["rune", "moonstone"]);
57	
58	// A group holds every item of one type, so the group's type identifies all of them.
59	type SameTypeGroup = { type: ItemType; items: Item[] };
60	
61	const groupByType = (items: Item[]): SameTypeGroup[] => {
62	  const itemsByType = new Map<ItemType, Item[]>();
63	  for (const item of items) {
64	    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
65	  }
66	  return [...itemsByType].map(([type, grouped]) => ({ type, items: grouped }));
67	};
68	
69	const isComponentBlock = (group: SameTypeGroup): boolean =>
70	  COMPONENT_TYPES.has(group.type) &&
71	  group.items.length === COMPONENT_BLOCK_SIZE;
72	
73	const isInsurable = (item: Item): boolean =>
74	  item.type in BASE_PREMIUM_BY_TYPE;
75	
76	const rejectUninsurableItems = (items: Item[]): void => {
77	  for (const item of items) {
78	    if (!isInsurable(item)) {
79	      throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
80	    }
81	  }
82	};
83	
84	const basePremiumFor = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
85	
86	const sumOf = <T>(values: T[], amountFor: (value: T) => number): number =>
87	  values.reduce((sum, value) => sum + amountFor(value), 0);
88	
89	const basePremiumForGroup = (group: SameTypeGroup): number =>
90	  isComponentBlock(group)
91	    ? COMPONENT_BLOCK_BASE_PREMIUM
92	    : sumOf(group.items, basePremiumFor);
93	
94	const totalBasePremium = (items: Item[]): number =>
95	  sumOf(groupByType(items), basePremiumForGroup);
96	
97	// A modifier is a signed rate applied to some base premium: a surcharge is
98	// positive, a discount negative. It only counts when its condition holds.
99	type Modifier = { rate: number; applies: boolean };
100	
101	const surcharge = (rate: number, applies: boolean): Modifier => ({
102	  rate,
103	  applies,
104	});
105	
106	const discount = (rate: number, applies: boolean): Modifier => ({
107	  rate: -rate,
108	  applies,
109	});
110	
111	const modifierAmount = (basePremium: number, modifier: Modifier): number =>
112	  modifier.applies ? basePremium * modifier.rate : 0;
113	
114	const totalModifierAmounts = (
115	  basePremium: number,
116	  modifiers: Modifier[],
117	): number =>
118	  sumOf(modifiers, (modifier) => modifierAmount(basePremium, modifier));
119	
120	const CURSE_SURCHARGE_RATE = 0.5;
121	const HIGH_ENCHANTMENT_LEVEL = 5;
122	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
123	
124	// An item without an enchantment counts as enchantment level 0.
125	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
126	
127	const isHighlyEnchanted = (item: Item): boolean =>
128	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
129	
130	// Item modifiers are rates on the item's own base premium.
131	const itemModifiersFor = (item: Item): Modifier[] => [
132	  surcharge(CURSE_SURCHARGE_RATE, item.cursed === true),
133	  surcharge(HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted(item)),
134	];
135	
136	const itemModifierTotalFor = (item: Item): number =>
137	  totalModifierAmounts(basePremiumFor(item), itemModifiersFor(item));
138	
139	const LOYALTY_YEARS = 2;
140	const LOYALTY_DISCOUNT_RATE = 0.2;
141	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
142	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
143	
144	const isLoyal = (customer: Customer): boolean =>
145	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
146	
147	// Policy modifiers are rates on the whole policy's base premium. Every quote's
148	// items count as a first insurance, whatever the customer's history.
149	const ALWAYS = true;
150	
151	const policyModifiersFor = (
152	  customer: Customer,
153	  isFollowUpContract: boolean,
154	): Modifier[] => [
155	  discount(LOYALTY_DISCOUNT_RATE, isLoyal(customer)),
156	  surcharge(FIRST_INSURANCE_SURCHARGE_RATE, ALWAYS),
157	  discount(FOLLOW_UP_DISCOUNT_RATE, isFollowUpContract),
158	];
159	
160	// The MHPCO rounds in its own favour: premiums up, payouts down.
161	const roundPremiumUpInMHPCOsFavour = (premium: number): number =>
162	  Math.ceil(premium);
163	
164	const quote = (
165	  items: Item[],
166	  customer: Customer,
167	  isFollowUpContract: boolean,
168	): QuoteResult => {
169	  rejectUninsurableItems(items);
170	  const basePremium = totalBasePremium(items);
171	  const itemModifiers = sumOf(items, itemModifierTotalFor);
172	  const policyModifiers = totalModifierAmounts(
173	    basePremium,
174	    policyModifiersFor(customer, isFollowUpContract),
175	  );
176	  return {
177	    premium: roundPremiumUpInMHPCOsFavour(
178	      basePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
179	    ),
180	  };
181	};
182	
183	const DEDUCTIBLE_PER_DAMAGE = 100;
184	
185	const insuranceValueFor = (item: Item): number =>
186	  INSURANCE_VALUE_BY_TYPE[item.type];
187	
188	const CAP_MULTIPLE = 2;
189	
190	const capFor = (items: Item[]): number =>
191	  CAP_MULTIPLE * sumOf(items, insuranceValueFor);
192	
193	const HALF_REIMBURSED_ENCHANTMENT_LEVEL = 8;
194	const HALF_REIMBURSEMENT_RATE = 0.5;
195	const FULL_REIMBURSEMENT_RATE = 1;
196	
197	// Damage to a very highly enchanted item is only half reimbursed.
198	const reimbursementRateFor = (item: Item): number =>
199	  enchantmentLevelOf(item) >= HALF_REIMBURSED_ENCHANTMENT_LEVEL
200	    ? HALF_REIMBURSEMENT_RATE
201	    : FULL_REIMBURSEMENT_RATE;
202	
203	const payoutForDamage = (damage: Damage, item: Item): number =>
204	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE;
205	
206	const roundPayoutDownInMHPCOsFavour = (payout: number): number =>
207	  Math.floor(payout);
208	
209	const insuredItemFor = (policy: Policy, damage: Damage): Item => {
210	  const item = policy.items.find(({ type }) => type === damage.itemType);
211	  if (item === undefined) {
212	    throw new Error(
213	      `The policy does not cover items of type "${damage.itemType}"`,
214	    );
215	  }
216	  return item;
217	};
218	
219	const claim = (policy: Policy, incident: Incident): ClaimResult => {
220	  const desiredPayout = roundPayoutDownInMHPCOsFavour(
221	    sumOf(incident.damages, (damage) =>
222	      payoutForDamage(damage, insuredItemFor(policy, damage)),
223	    ),
224	  );
225	  // The desired payout is capped by whatever the policy has left.
226	  const payout = Math.min(desiredPayout, policy.remainingCap);
227	  policy.remainingCap -= payout;
228	  return { payout, remainingCap: policy.remainingCap };
229	};
230	
231	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
232	
233	// A step is a follow-up contract when the customer already holds one from an
234	// earlier step of this scenario, so every quote but the first.
235	export const runScenario = (scenario: Scenario): { results: Result[] } => {
236	  const policies = new Map<number, Policy>();
237	  const results: Result[] = [];
238	
239	  scenario.steps.forEach((step, index) => {
240	    if (isQuoteStep(step)) {
241	      results.push(quote(step.items, scenario.customer, policies.size > 0));
242	      policies.set(index, {
243	        items: step.items,
244	        remainingCap: capFor(step.items),
245	      });
246	      return;
247	    }
248	    const policy = policies.get(step.policy);
249	    if (policy === undefined) {
250	      throw new Error(`No policy was created by step ${step.policy}`);
251	    }
252	    results.push(claim(policy, step.incident));
253	  });
254	
255	  return { results };
256	};
